import { NextResponse } from "next/server";
import { findPublishedBanner } from "../../../../lib/aliexpress/banners";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
const noStore = { "Cache-Control": "no-store" };

// Resolves a banner id to the link generated by aliexpress.affiliate.link.generate.
// The destination never comes from the visitor; expired or blocked banners 404.
export async function GET(_request: Request, context: { params: Promise<{ id: string }> }) {
  const { id } = await context.params;
  if (!/^[pf]-[a-z0-9-]{1,80}$/.test(id)) return new Response("Not found", { status: 404, headers: noStore });
  let banner;
  try {
    banner = await findPublishedBanner(id);
  } catch {
    banner = null;
  }
  if (!banner?.link) return new Response("Banner unavailable", { status: 404, headers: noStore });
  const url = new URL(banner.link);
  const host = url.hostname.toLowerCase();
  if (url.protocol !== "https:" || !["aliexpress.com", "aliexpress.us"].some((d) => host === d || host.endsWith("." + d)))
    return new Response("Invalid destination", { status: 502, headers: noStore });
  const response = NextResponse.redirect(url, 307);
  response.headers.set("Cache-Control", "no-store, max-age=0");
  response.headers.set("Referrer-Policy", "no-referrer");
  response.headers.set("X-Robots-Tag", "noindex, nofollow");
  return response;
}
